    "Show Selection Actions when selecting text": "选中文本时显示划词操作",
    "Show \"Edit\" and \"Chat\" buttons when selecting text in the editor.": "在编辑器中选中代码或文本时，浮动显示“编辑”与“聊天”快捷按钮。",
